  m('Cần chờ hết hạn nộp của kỳ thật (không thể rút ngắn kỳ đang diễn ra)', 'RES-W16', U3, 'Đánh giá lại', 'Đơn vị không gửi lại kịp trước hạn thì bản đã gửi trước đó vẫn là kết quả chính thức (BR-3)', 'Nghiệp vụ', 'Trung bình', '1. Yêu cầu đánh giá lại, đơn vị không gửi lại\n2. Sau hạn nộp xem danh sách, Hồ sơ gửi Bộ', 'Kết quả hiển thị bản đã gửi trước đó là chính thức; điểm giữ nguyên');
  c('RES-W17', U3, 'Đánh giá lại', 'Bản đã gửi trước đó vẫn được lưu trong Hồ sơ gửi Bộ sau khi yêu cầu đánh giá lại', 'Nghiệp vụ', 'Trung bình', '1. Yêu cầu đánh giá lại\n2. Mở Hồ sơ gửi Bộ', 'Lần gửi cũ vẫn hiển thị với file và thời gian');
  c('RES-W18', U3, 'Đánh giá lại', 'Kết quả đang Chờ mở khóa không yêu cầu đánh giá lại được (MSG-060)', 'Nghiệp vụ', 'Cao', '1. [API] POST /reassess trên kết quả Chờ mở khóa', '400 báo trạng thái không hợp lệ; trạng thái giữ nguyên', 'Khảo sát: 400 "Chỉ có thể yêu cầu đánh giá lại khi kết quả đang ở trạng thái Đã gửi" (khác MSG-060)');
  c('RES-W19', U3, 'Đánh giá lại', 'Kết quả đã Bị từ chối không yêu cầu lại lần 2 (lặp thao tác)', 'Nghiệp vụ', 'Cao', '1. Yêu cầu đánh giá lại thành công\n2. [API] POST /reassess lần 2', 'Lần 2 bị từ chối 4xx báo trạng thái không hợp lệ; chỉ có 1 dòng lịch sử', 'Khảo sát: lần 2 trả 403 "Bạn không có quyền truy cập chức năng này" thay vì thông báo trạng thái (MSG-060) → nghi sai mã/thông báo');
  c('RES-W20', U3, 'Đánh giá lại', 'Kết quả chưa gửi (Chưa thực hiện, Đang chấm điểm, Đã phê duyệt) không yêu cầu đánh giá lại được', 'Nghiệp vụ', 'Trung bình', '1. [API] POST /reassess trên kết quả Đang chấm điểm và Đã phê duyệt', '4xx; trạng thái giữ nguyên', 'Khảo sát: 403 "Bạn không có quyền…" thay vì MSG-060');
  c('RES-W21', U3, 'Đánh giá lại', 'Kỳ đã kết thúc: kết quả Đã gửi không có mục Yêu cầu đánh giá lại, API từ chối (MSG-061)', 'Nghiệp vụ', 'Cao', '1. Mở menu dòng Đã gửi thuộc kỳ đã kết thúc\n2. [API] POST /reassess', 'Menu không có mục; API 4xx báo kỳ đã kết thúc', 'Khảo sát: API 403 chung "Bạn không có quyền…"');
  c('RES-W22', U3, 'Đánh giá lại', 'Lãnh đạo Bộ, Lãnh đạo đơn vị, Lãnh đạo địa phương không có quyền Yêu cầu đánh giá lại: ẩn mục và API 403 (EF3)', 'Bảo mật', 'Cao', '1. Đăng nhập từng vai trò, mở menu dòng Đã gửi\n2. [API] POST /reassess', 'Không có mục Yêu cầu đánh giá lại; API 403 và trạng thái giữ nguyên', 'Khảo sát: thông báo 403 "Bạn không có quyền truy cập chức năng này" (SRS MSG-043)');
  c('RES-W23', U3, 'Đánh giá lại', 'Cán bộ địa phương không yêu cầu đánh giá lại được kết quả của đơn vị ngoài phạm vi', 'Bảo mật', 'Cao', '1. [API] CB địa phương POST /reassess với resultId đơn vị ngoài phạm vi', '403/404, trạng thái giữ nguyên');
  c('RES-W24', U3, 'Đánh giá lại', 'Lý do chứa HTML / ký tự đặc biệt / Unicode được lưu nguyên và hiển thị an toàn', 'Bảo mật', 'Trung bình', '1. Nhập lý do <b>x</b> & "q" ế\n2. Gửi\n3. Xem Lịch sử, cảnh báo và thông báo của đơn vị', 'Hiển thị đúng nguyên văn dạng text, không render HTML, không lỗi');
  c('RES-W25', U3, 'Đánh giá lại', 'Bấm Gửi yêu cầu hai lần liên tiếp chỉ tạo một yêu cầu', 'Nghiệp vụ', 'Trung bình', '1. Nhập lý do\n2. Bấm Gửi yêu cầu 2 lần nhanh', 'Chỉ 1 dòng lịch sử và 1 thông báo TB-012; nút bị vô hiệu khi đang gửi');
  c('RES-W26', U3, 'Đánh giá lại', 'Yêu cầu đánh giá lại kết quả kỳ Định kỳ thành công', 'Chức năng', 'Trung bình', '1. Kỳ định kỳ đang diễn ra có kết quả Đã gửi\n2. Yêu cầu đánh giá lại', 'Thành công; kết quả sang Bị từ chối', 'Cần dựng kỳ định kỳ thử');
  c('RES-W27', U3, 'Đánh giá lại', 'Yêu cầu đánh giá lại kết quả kỳ Đột xuất thành công (UC_1409 237)', 'Chức năng', 'Trung bình', '1. Kỳ đột xuất đang diễn ra có kết quả Đã gửi\n2. Yêu cầu đánh giá lại', 'Thành công; kết quả sang Bị từ chối');
  c('RES-W28', U3, 'Đánh giá lại', 'Bộ không chấm lại điểm: sau yêu cầu điểm đã gửi giữ nguyên và Bộ không có thao tác sửa điểm', 'Nghiệp vụ', 'Trung bình', '1. Yêu cầu đánh giá lại\n2. Mở chi tiết bằng Lãnh đạo Bộ', 'Điểm giữ nguyên; không có nút Chấm điểm/Lưu cho Lãnh đạo Bộ');

