  c('RES-O20', U4a, 'Duyệt mở khóa', 'Duyệt mở khóa với id không tồn tại trả 404 không lộ lỗi nội bộ', 'Validate', 'Trung bình', '1. [API] POST /approve-unlock với GUID ngẫu nhiên và id "abc"', '404 "Không tìm thấy kết quả tự đánh giá"; không 500');
