  c('RES-O22', U4a, 'Duyệt mở khóa', 'Duyệt mở khóa không đổi điểm đã chấm và các bản đã gửi của đơn vị', 'Nghiệp vụ', 'Trung bình', '1. Ghi điểm, số bản gửi\n2. Duyệt mở khóa\n3. So sánh', 'Điểm từng chỉ số và số bản gửi giữ nguyên; điểm hiển thị là tạm tính');
